// Section 7: The physics supporting the results in ACI research.
// Exports a function that returns an array of docx block elements.
const fs = require("fs");
const path = require("path");
const {
  Paragraph, TextRun, HeadingLevel, AlignmentType, Table, TableRow, TableCell, WidthType,
  BorderStyle, VerticalAlign, ImageRun,
  Math: DMath, MathRun, MathFraction, MathSuperScript, MathSubScript, MathSubSuperScript,
  MathRadical, MathRoundBrackets, MathSquareBrackets, MathIntegral, MathFunction
} = require("docx");

module.exports = function buildSection7(ctx) {
  const { H, rich, cell, tw, FONT, BODY } = ctx;
  const out = [];
  const FIGDIR = path.join(__dirname, "figs");

  // ---------- text helpers ----------
  const P = (t) => new Paragraph({ children: rich(t), spacing: { after: 160, line: 276 }, alignment: AlignmentType.JUSTIFIED });
  const PB = (lead, t) => new Paragraph({
    children: [new TextRun({ text: lead, bold: true, font: FONT, size: BODY })].concat(rich(t)),
    spacing: { after: 160, line: 276 }, alignment: AlignmentType.JUSTIFIED
  });
  const H2 = (t) => H(t, HeadingLevel.HEADING_2);

  // ---------- math helpers ----------
  const m = (x) => (Array.isArray(x) ? x : [x]).flat(Infinity).map((v) => (typeof v === "string" ? new MathRun(v) : v));
  const fr = (a, b) => new MathFraction({ numerator: m(a), denominator: m(b) });
  const sup = (a, b) => new MathSuperScript({ children: m(a), superScript: m(b) });
  const sub = (a, b) => new MathSubScript({ children: m(a), subScript: m(b) });
  const ss = (a, b, c) => new MathSubSuperScript({ children: m(a), subScript: m(b), superScript: m(c) });
  const rt = (a) => new MathRadical({ children: m(a) });
  const pr = (a) => new MathRoundBrackets({ children: m(a) });
  const br = (a) => new MathSquareBrackets({ children: m(a) });
  const integ = (a) => new MathIntegral({ children: m(a) });
  const fn = (name, a) => new MathFunction({ name: [new MathRun(name)], children: m(a) });
  const GAP = "\u2003\u2003\u2003";   // wide space between two formulas on one line

  const NB = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
  const NOB = { top: NB, bottom: NB, left: NB, right: NB };
  const eqCell = (w, kids, align) => new TableCell({
    width: { size: w, type: WidthType.DXA }, borders: NOB, verticalAlign: VerticalAlign.CENTER,
    margins: { top: 40, bottom: 40, left: 60, right: 60 },
    children: [new Paragraph({ children: kids, alignment: align, spacing: { before: 60, after: 60 } })]
  });
  let eqN = 0;
  const Eq = (parts) => {
    eqN += 1;
    return [
      new Table({
        width: { size: tw, type: WidthType.DXA }, columnWidths: [900, tw - 1800, 900],
        borders: { top: NB, bottom: NB, left: NB, right: NB, insideHorizontal: NB, insideVertical: NB },
        rows: [new TableRow({
          cantSplit: true,
          children: [
            eqCell(900, [new TextRun({ text: "", font: FONT, size: BODY })], AlignmentType.LEFT),
            eqCell(tw - 1800, [new DMath({ children: m(parts) })], AlignmentType.CENTER),
            eqCell(900, [new TextRun({ text: `(7.${eqN})`, font: FONT, size: BODY })], AlignmentType.RIGHT)
          ]
        })]
      }),
      new Paragraph({ children: [new TextRun({ text: "", font: FONT, size: 8 })], spacing: { after: 60, line: 120 } })
    ];
  };

  // two formulas side by side under one equation number
  const Eq2 = (a, b, wA = 4080) => {
    eqN += 1;
    const wB = tw - 1200 - wA;
    return [
      new Table({
        width: { size: tw, type: WidthType.DXA }, columnWidths: [300, wA, wB, 900],
        borders: { top: NB, bottom: NB, left: NB, right: NB, insideHorizontal: NB, insideVertical: NB },
        rows: [new TableRow({
          cantSplit: true,
          children: [
            eqCell(300, [new TextRun({ text: "", font: FONT, size: BODY })], AlignmentType.LEFT),
            eqCell(wA, [new DMath({ children: m(a) })], AlignmentType.CENTER),
            eqCell(wB, [new DMath({ children: m(b) })], AlignmentType.CENTER),
            eqCell(900, [new TextRun({ text: `(7.${eqN})`, font: FONT, size: BODY })], AlignmentType.RIGHT)
          ]
        })]
      }),
      new Paragraph({ children: [new TextRun({ text: "", font: FONT, size: 8 })], spacing: { after: 60, line: 120 } })
    ];
  };

  // ---------- figure helper ----------
  let figN = 0;
  const Fig = (file, caption, alt) => {
    figN += 1;
    const buf = fs.readFileSync(path.join(FIGDIR, file));
    const wpx = buf.readUInt32BE(16), hpx = buf.readUInt32BE(20);
    const W = 600, Hh = Math.round((W * hpx) / wpx);
    return [
      new Paragraph({
        alignment: AlignmentType.CENTER, keepNext: true, spacing: { before: 120, after: 80 },
        children: [new ImageRun({ type: "png", data: buf, transformation: { width: W, height: Hh },
          altText: { title: `Figure ${figN}`, description: alt, name: `Figure ${figN}` } })]
      }),
      new Paragraph({
        children: [new TextRun({ text: `Figure ${figN}. `, bold: true, font: FONT, size: 20 })].concat(rich(caption, { size: 20 })),
        spacing: { after: 240, line: 260 }, alignment: AlignmentType.LEFT, keepLines: true
      })
    ];
  };
  const push = (...xs) => xs.forEach((x) => (Array.isArray(x) ? x.forEach((y) => out.push(y)) : out.push(x)));

  // =====================================================================================
  push(H("7. The physics supporting the results in ACI research", HeadingLevel.HEADING_1));
  push(P(`Sections 2–6 report results. This section explains why those results look the way they do. It is written to build intuition, not to be complete: each subsection poses one question, builds a picture, writes down the one or two equations that carry the argument, works a number, and then lists the results in Sections 2–6 that the argument explains. The material comes from five sources: the cloud physics text of Rogers and Yau (1989), the radiative transfer text of Bohren and Clothiaux (2006), Robert Wood's notes on seminal papers for his graduate course on aerosol–cloud–climate interactions at the University of Washington (Wood, 2015), two lecture decks from an MIT course on experimental atmospheric chemistry (Ardon-Dryer and Garimella, 2014a, 2014b), and the encyclopedia article of Li et al. (2017). Each statement is cited to the place where it can be followed up.`));
  push(P(`The figures were drawn for this review. Every curve is computed from an equation in one of the sources, and where a source tabulates values they are overplotted as open markers so that agreement can be checked by eye. Anything that is illustrative, or that was derived here from the source equations and is not itself in a source, is labeled as such in the text or caption. Where this section and the textbooks differ, the textbooks are right.`));

  // ------------------------------------------------------------------ 7.1
  push(H2("7.1 The causal chain in one picture"));
  push(P(`Every result in Sections 2–6 is a statement about one link in the chain of Figure 1, or about the loop beneath it. The top row is the Twomey effect. More aerosol particles produce more droplets (Sections 7.2–7.4). The same condensed water shared among more droplets makes each one smaller (Sections 7.5 and 7.7). Smaller droplets present more cross-sectional area per unit mass of water, so the optical depth of the cloud rises (Section 7.7). A cloud of larger optical depth reflects more sunlight (Section 7.8). The bottom row holds what the literature calls adjustments: droplet size also controls how readily the cloud rains (Section 7.6) and how fast its droplets settle and evaporate near cloud top (Section 7.10). Both change the amount of liquid water, and optical depth is more sensitive to liquid water than to droplet number. Li et al. (2017) divide the subject the same way, into the Twomey effect at fixed water and the subsequent changes in cloud water, lifetime and cover.`));
  push(PB("Notation. ", `N_{d} is the droplet number concentration; s is the supersaturation in percent, s = (S − 1) × 100, where S is the saturation ratio; r is droplet radius and r_{e} the effective radius; L is the liquid water content (mass of liquid per unit volume of air) and LWP its vertical integral; h is cloud thickness; w is updraft speed; τ is optical depth; α is cloud albedo; g is the asymmetry parameter. An asterisk (∗) marks a critical value.`));
  push(Fig("fig01_chain.png", `The causal chain of aerosol–cloud interactions and the subsections that treat each link. Top row: the Twomey effect at fixed liquid water. Bottom row: the adjustments, through which droplet size changes the liquid water path (LWP) and so feeds back on optical depth. Schematic drawn for this review.`,
    "Flow diagram: aerosol leads to droplet number, droplet size, optical depth and albedo; droplet size also leads to rain formation and to entrainment and evaporation, which change liquid water path and feed back on optical depth."));

  // ------------------------------------------------------------------ 7.2
  push(H2("7.2 Why a droplet needs a particle: curvature against solute"));
  push(PB("The question. ", `Why does cloud water condense on aerosol particles and not directly from the vapor, and why do some particles serve better than others?`));
  push(P(`Start with a droplet of pure water. A molecule at a curved surface has fewer neighbors holding it in than a molecule at a flat surface, so it escapes more easily, and the vapor pressure needed to keep the droplet from evaporating is higher than over a flat surface. The smaller the droplet, the sharper the curvature and the larger the penalty. This is the Kelvin effect (Rogers and Yau, 1989, Eq. 6.1):`));
  push(Eq([fr([sub("e", "s"), pr("r")], [sub("e", "s"), pr("∞")]), " = ", fn("exp", pr(fr("2σ", ["r ", sub("R", "v"), " ", sub("ρ", "L"), " T"])))]));
  push(P(`Here σ is the surface tension of water (about 7.5 × 10⁻² N m⁻¹), ρ_{L} the density of liquid water, R_{v} the gas constant for water vapor and T the temperature. Numbers make the point. A pure droplet of radius 0.12 μm is in equilibrium only at a saturation ratio of 1.01, and one of radius 0.0017 μm needs a saturation ratio of 2 (Rogers and Yau, 1989, Table 6.1; reproduced by Ardon-Dryer and Garimella, 2014b). A droplet has to start small, so forming one from vapor alone would need a saturation ratio of about 4.3 at 273 K (Rogers and Yau, 1989), or 300–600% relative humidity (Ardon-Dryer and Garimella, 2014b), whereas supersaturation in the atmosphere rarely exceeds 1–2% (Rogers and Yau, 1989). Clouds cannot form this way.`));
  push(P(`A dissolved salt pulls in the opposite direction. Solute ions take up part of the surface and hold on to water molecules, so the equilibrium vapor pressure over a solution is lower than over pure water (Raoult's law; Rogers and Yau, 1989, Eq. 6.4). A given mass of salt is most concentrated when the droplet is smallest, so this effect also grows as the droplet shrinks, and it grows faster than the curvature penalty: the solute term goes as 1/r³, because the concentration depends on the droplet's volume, while the curvature term goes as 1/r. Adding the two gives the Köhler curve (Rogers and Yau, 1989, Eq. 6.6; Ardon-Dryer and Garimella, 2014b):`));
  push(Eq(["S ≈ 1 + ", fr("a", "r"), " − ", fr("b", sup("r", "3"))]));
  push(P(`with a ≈ 3.3 × 10⁻⁵/T (in cm, with T in kelvin) and b ≈ 4.3 i M/m_{s} (in cm³), where M is the mass of solute in grams, m_{s} its molecular weight, and i the number of ions each dissolved molecule supplies. Rogers and Yau (1989) take i = 2 as a reasonable approximation for both sodium chloride and ammonium sulfate.`));
  push(P(`Figure 2a shows the two terms and their sum for a particle of ammonium sulfate of mass 10⁻¹⁶ g. At small radius the solute term wins, and the droplet is in equilibrium below 100% relative humidity. This is a haze droplet, and it is stable: if it gains a little water its equilibrium humidity rises above that of the surrounding air and it evaporates back. At large radius both terms fade and the curve returns toward saturation from above. In between is a peak, at the critical radius r^{∗} and critical supersaturation s^{∗}. If the ambient supersaturation exceeds s^{∗} the droplet passes the peak, and from then on every increment of growth lowers the humidity it needs. It is activated, and it grows freely for as long as the air stays supersaturated (Rogers and Yau, 1989, Ch. 6; Ardon-Dryer and Garimella, 2014b). Setting the derivative of Eq. 7.2 to zero locates the peak (Rogers and Yau, 1989, Eqs. 6.7–6.8):`));
  push(Eq2([sup("r", "∗"), " = ", rt(fr("3b", "a"))], [sup("s", "∗"), " = ", sup("S", "∗"), " − 1 = ", rt(fr(["4", sup("a", "3")], "27b"))]));
  push(P(`Because b is proportional to the mass of solute, s^{∗} falls as the inverse square root of the dry mass, or as dry diameter to the power −3/2. A tenfold increase in salt mass lowers the barrier by a factor of about three: at 273 K, sodium chloride particles of 10⁻¹⁶, 10⁻¹⁵ and 10⁻¹⁴ g activate at 0.42%, 0.13% and 0.042% (Rogers and Yau, 1989, Table 6.2; Figure 2b). This is the first piece of intuition for the whole field. In a rising air parcel the supersaturation climbs from zero, so the largest and most soluble particles activate first.`));
  push(Fig("fig02_kohler.png", `Köhler curves. (a) Equilibrium supersaturation over a solution droplet holding 10⁻¹⁶ g of ammonium sulfate at 273 K, as the sum of the curvature term and the solute term of Eq. 7.2. The critical point reproduces the values Rogers and Yau (1989) quote for their Fig. 6.2 (r^{∗} = 0.13 μm, s^{∗} = 0.6%). (b) Curves for three masses of sodium chloride; open circles are the critical radii and supersaturations tabulated by Rogers and Yau (1989, Table 6.2).`,
    "Two panels of equilibrium supersaturation against droplet radius. Left: curvature term, solute term and their sum with a marked critical point. Right: Köhler curves for three salt masses with tabulated critical points."));
  push(P(`Chemistry enters through b. Different compounds supply different numbers of dissolved ions per unit dry volume, and insoluble material supplies none; an insoluble component raises the supersaturation that a particle of given size needs (Ardon-Dryer and Garimella, 2014b). Petters and Kreidenweis (2007) compressed all of this into a single hygroscopicity parameter κ, in a form of the Köhler equation written in terms of the dry diameter D_{d} and the wet diameter D:`));
  push(Eq2(["S", pr("D"), " = ", fr([sup("D", "3"), " − ", ss("D", "d", "3")], [sup("D", "3"), " − ", ss("D", "d", "3"), pr("1 − κ")]), " ", fn("exp", pr(fr("A", "D")))], ["A = ", fr(["4σ", sub("M", "w")], ["RT", sub("ρ", "w")])], 5000));
  push(P(`κ is about 0.5–1.4 for highly CCN-active salts such as sodium chloride, 0.01–0.5 for slightly to very hygroscopic organic species, and 0 for non-hygroscopic material; atmospheric particulate matter typically falls between 0.1 and 0.9 (Petters and Kreidenweis, 2007). For κ larger than about 0.2 the peak of Eq. 7.4 is well approximated by (Petters and Kreidenweis, 2007):`));
  push(Eq([fn("ln", sub("S", "c")), " ≈ ", rt(fr(["4", sup("A", "3")], ["27 κ ", ss("D", "d", "3")]))]));
  push(P(`which has the same diameter dependence as Eq. 7.3, with κ in the role of solubility. Figure 3 plots the exact maximum of Eq. 7.4. Two things stand out. First, size counts for more than composition: doubling the diameter lowers the critical supersaturation by a factor of 2^{3/2} ≈ 2.8, whereas doubling κ lowers it by a factor of 2^{1/2} ≈ 1.4. That is the quantitative content of the phrase 'size matters more than chemistry' (Dusek et al., 2006, as cited in Wood, 2015, notes on McFiggans et al., 2006). Second, the figure can be read backwards. If a cloud is known to have activated every particle larger than some diameter, and κ is known, the curve returns the supersaturation the cloud reached. That is one of the supersaturation retrievals Dedrick et al. (2026) apply at EPCAPE (Section 7.3), and the box in Figure 3 marks their values.`));
  push(Fig("fig03_kappa.png", `Critical supersaturation against dry diameter for four values of the hygroscopicity parameter κ, from the maximum of Eq. 7.4 (Petters and Kreidenweis, 2007) at 298.15 K with σ = 0.072 J m⁻², the values used by Ardon-Dryer and Garimella (2014b). The box marks the mean ambient Hoppel-minimum diameters at Mt. Soledad and Scripps Pier (62 ± 20 and 75 ± 30 nm) and the range of mean supersaturation retrieved from the Hoppel minimum (0.28–0.40%); the shaded band marks the cloud-scene and parcel retrievals (0.03–0.13%) (Dedrick et al., 2026). The bimodal-cluster κ at the two sites was 0.50 and 0.42.`,
    "Log-log plot of critical supersaturation against dry particle diameter for kappa of 0.1, 0.3, 0.6 and 1.2, with EPCAPE values marked."));
  push(P(`One more piece of chemistry helps when aerosol is measured below cloud. A dry salt particle does not take up water gradually. It stays dry until the relative humidity reaches its deliquescence point (75.3% for sodium chloride, 79.9% for ammonium sulfate), where it dissolves abruptly into a solution droplet, and on drying it stays liquid until the much lower efflorescence point (43% and 35%) (Ardon-Dryer and Garimella, 2014b). In the humid marine boundary layer, soluble particles are therefore usually haze droplets already swollen with water. An inference from this, and from the steep rise of extinction with size at aerosol sizes (Figure 9), is that the light extinction measured as aerosol optical depth depends on the water the particles have taken up as well as on their number; Section 5.3 reviews the evidence that optical depth is a weak proxy for CCN.`));
  push(PB("What this explains. ", `Twomey's starting point, that droplet number is set by the particles able to act as nuclei (Section 2). Why CCN are always quoted at a stated supersaturation. Why the Hoppel-minimum diameter can be converted to a cloud supersaturation (Sections 3.2, 5.4 and 6.5). Why hygroscopicity variations had a weaker effect than accumulation-mode number in the sensitivity experiments of Wang et al. (2026) (Section 6.4).`));

  // ------------------------------------------------------------------ 7.3
  push(H2("7.3 From a population of particles to a CCN spectrum"));
  push(PB("The question. ", `Which particles in a real aerosol become droplets, and how is that population described?`));
  push(P(`Atmospheric particles span more than four orders of magnitude in size. The MIT lecture divides them into a nucleation mode (about 0.001–0.01 μm), an Aitken mode (0.01–0.1 μm), an accumulation mode (0.1–1 μm) and a coarse mode (larger than 1 μm) (Ardon-Dryer and Garimella, 2014a). Primary particles, such as sea salt from bubbles bursting at the sea surface, are emitted directly. Secondary particles form in the atmosphere from gases: sulfate from the oxidation of sulfur dioxide, nitrate from nitrogen oxides (Ardon-Dryer and Garimella, 2014a). The accumulation mode is named for the way particles smaller than about 0.1 μm collide through Brownian motion and clump into it, while sedimentation limits the largest sizes (Rogers and Yau, 1989, Ch. 6). Particles may be internally mixed, each one a blend of compounds, or externally mixed, with different particles of different composition; the distinction matters because Eq. 7.4 applies particle by particle (Ardon-Dryer and Garimella, 2014a; Wood, 2015, notes on McFiggans et al., 2006).`));
  push(P(`Put Figure 3 next to a size distribution and the answer to 'which particles activate' is immediate. For a given supersaturation there is a critical dry diameter, and every sufficiently hygroscopic particle larger than it becomes a droplet. Figure 4a shows this for an illustrative two-mode distribution. With κ = 0.45, a supersaturation of 0.1% activates particles larger than about 150 nm, which is only the large side of the accumulation mode. At 0.3% the threshold drops to about 72 nm and most of the accumulation mode is in. The Aitken mode stays out in both cases.`));
  push(P(`The same picture explains the Hoppel minimum (Section 3.2). Particles that activate spend time as droplets, where dissolved gases are converted to non-volatile solute and where droplets collect smaller interstitial particles. When the cloud evaporates, each activated particle is left larger than it started, while particles that never activated are unchanged. After repeated cloud cycles a gap opens in the size distribution at the diameter that separated the two groups (Hoppel et al., 1986, 1994). Reading that diameter off the size distribution and entering Figure 3 gives the effective supersaturation of the clouds that processed the air (Hoppel et al., 1996; Hudson et al., 2015). Dedrick et al. (2026) note that a minimum built up over many cloud cycles records the highest supersaturation among them, which is why their Hoppel-minimum values exceed their cloud-scene values in Figure 3.`));
  push(P(`Cloud physicists summarize the outcome without tracking each particle. A CCN counter holds sampled air at a fixed, small supersaturation and counts the droplets that form. Stepping the supersaturation gives the cumulative number of particles that activate at or below each value, the CCN activity spectrum, which is often fitted by a power law (Rogers and Yau, 1989, Eq. 6.20; Ardon-Dryer and Garimella, 2014b):`));
  push(Eq([sub("N", "CCN"), pr("s"), " = C ", sup("s", "k")]));
  push(P(`with s in percent, so that C is the concentration active at 1% supersaturation. Typical ranges are C = 30–300 cm⁻³ and k = 0.3–1.0 in maritime air and C = 300–3000 cm⁻³ and k = 0.2–2.0 in continental air (Rogers and Yau, 1989). Figure 4b plots the two examples used in the MIT lecture. C says how many nuclei there are. The exponent k says how they are distributed: a spectrum that keeps rising steeply with s has many small particles waiting just below the activation threshold. Equation 7.6 is the input to Twomey's theory in the next subsection.`));
  push(Fig("fig04_ccn.png", `From a size distribution to an activity spectrum. (a) An illustrative two-mode number size distribution (parameters chosen for this review, not measured). Shading marks the particles that activate at 0.1% supersaturation (dry diameter above about 150 nm) and the additional particles that activate at 0.3% (down to about 72 nm), from Eq. 7.4 with κ = 0.45. The gap between the modes is the Hoppel minimum. (b) CCN activity spectra N = C s^{k} for the marine and continental parameters given by Ardon-Dryer and Garimella (2014b).`,
    "Left: bimodal aerosol size distribution with shaded activated fractions and the Hoppel minimum marked. Right: marine and continental CCN activity spectra against supersaturation."));
  push(PB("What this explains. ", `Why the Hoppel minimum is both a signature of cloud processing and a supersaturation gauge (Sections 3.2, 5.4 and 6.5). Why an aerosol index weighted toward particle number, or CCN at a stated supersaturation, predicts droplet size better than optical depth does (Sections 4.1, 5.3 and 6.1). Why accumulation-mode number is the dominant control on N_{d} at the Eastern North Atlantic site (Section 6.4).`));

  // ------------------------------------------------------------------ 7.4
  push(H2("7.4 How many droplets form: the supersaturation tug-of-war"));
  push(PB("The question. ", `The aerosol supplies candidates. What decides how many of them activate?`));
  push(P(`The answer is the peak supersaturation reached just above cloud base, and that peak is the outcome of a contest. As a parcel of air rises it expands and cools, which raises its relative humidity. This is the source of supersaturation, and it is proportional to the updraft speed. As soon as droplets exist they condense vapor, which lowers the humidity. This is the sink, and it grows with the number of droplets and with their size. Rogers and Yau (1989, Eqs. 7.21–7.24) write the budget as`));
  push(Eq([fr("dS", "dt"), " = ", sub("Q", "1"), " ", fr("dz", "dt"), " − ", sub("Q", "2"), " ", fr("dχ", "dt")]));
  push(P(`where dz/dt is the updraft speed, χ is the mass of condensed water per unit mass of air, and Q_{1} and Q_{2} are thermodynamic coefficients that depend on temperature and pressure.`));
  push(P(`Follow the parcel through cloud base (Figure 5). At first there are no droplets, the sink is zero, and the supersaturation climbs at a rate set by the updraft. As it climbs it crosses the critical supersaturations of more and more particles (Eq. 7.6), each of which begins to grow and to consume vapor. The sink strengthens until it equals the source, and at that instant the supersaturation peaks. From then on the growing droplets win, the supersaturation relaxes, and no new particles activate. Droplet number is therefore fixed within the first tens of meters above cloud base, and it equals the number of CCN whose critical supersaturation lies below the peak. Rogers and Yau (1989, Fig. 7.4) show this behavior from a numerical parcel model, with the peak reached within about 100 m of cloud base.`));
  push(Fig("fig05_parcel.png", `Supersaturation and droplet number in a rising parcel for a CCN spectrum with C = 650 cm⁻³ and k = 0.7, the case of Rogers and Yau (1989, Fig. 7.4), at two updraft speeds. The curves are from a simplified parcel integration written for this review (Eq. 7.7, with each CCN class activating at its critical supersaturation and then growing by Eq. 7.10; 283 K, 90 kPa). Triangles on the upper axis mark the peak supersaturation and droplet number from Twomey's formulas (Eqs. 7.8–7.9). The simplified integration peaks 15–17% lower and gives about 8% fewer droplets than the formulas; it illustrates the mechanism and does not replace the source calculation.`,
    "Two panels against height above cloud base: supersaturation rising to a peak and relaxing, and activated droplet number rising then leveling off, for updrafts of 0.5 and 2 meters per second."));
  push(P(`Twomey (1959) solved the problem approximately in closed form. For an activity spectrum of the form of Eq. 7.6 with k between 0.4 and 1.0, his results can be written (Rogers and Yau, 1989, Eqs. 6.21–6.22):`));
  push(Eq([sub("N", "d"), " ≈ 0.88 ", sup("C", "2/(k+2)"), " ", sup(br(["7 × ", sup("10", "−2"), " ", sup("w", "3/2")]), "k/(k+2)")]));
  push(Eq([sub("s", "max"), " ≈ 3.6 ", sup(br(fr(["1.6 × ", sup("10", "−3"), " ", sup("w", "3/2")], "C")), "1/(k+2)")]));
  push(P(`with N_{d} and C in cm⁻³, the updraft w in cm s⁻¹ (Rogers and Yau write it U), and s_{max} in percent.`));
  push(P(`The exponents carry the physics. Because 2/(k + 2) is less than one, droplet number rises more slowly than CCN number. With k = 0.5, doubling C multiplies N_{d} by 2^{0.8} = 1.74, not 2. Equation 7.9 says where the missing droplets went: doubling C lowers the peak supersaturation by a factor of 2^{−0.4} = 0.76, so the smallest of the added particles never activate. This is competition for water vapor. A worked case, for an updraft of 0.5 m s⁻¹ and k = 0.5: C = 100 cm⁻³ gives N_{d} ≈ 67 cm⁻³ at a peak of 0.45%; C = 200 cm⁻³ gives 116 cm⁻³ at 0.34%; C = 1000 cm⁻³ gives 420 cm⁻³ at 0.18% (numbers computed here from Eqs. 7.8–7.9; Figure 6 shows the same behavior for k = 0.7). The updraft works the other way. A stronger updraft strengthens the source, the peak is higher, and more of the spectrum activates, with N_{d} proportional to w^{3k/(2k+4)}. Equation 7.8 also gives dln N_{d}/dln C = 2/(k + 2), which lies between 0.67 and 0.83 for k between 0.4 and 1.0.`));
  push(Fig("fig06_twomey.png", `Twomey's activation formulas (Eqs. 7.8–7.9; Rogers and Yau, 1989, Eqs. 6.21–6.22) for k = 0.7 and three updraft speeds. (a) Droplet number against the CCN parameter C. The dashed line N_{d} = C is what would result if every nucleus active at 1% supersaturation became a droplet. (b) The corresponding peak supersaturation, which falls as nuclei are added.`,
    "Two log-log panels against CCN concentration: droplet number rising sub-linearly, and peak supersaturation falling, for updrafts of 0.1, 0.5 and 2 meters per second."));
  push(P(`Taken to its limits, the same contest gives the regimes of Reutter et al. (2009) described in Section 4.4. When particles are few relative to the updraft, the sink is weak, the peak is high, nearly every particle activates, and N_{d} follows the aerosol: the aerosol-limited regime. When particles are many relative to the updraft, the peak is so low that only the largest activate, and adding particles mostly lowers the peak further: the updraft-limited regime. Wood's notes on McFiggans et al. (2006) list the same sensitivities. More particles, larger particles, more soluble particles and stronger updrafts each give more droplets; a wider size distribution gives fewer, through competition; and sea-salt particles, being large, lower the peak supersaturation for everything else (Wood, 2015).`));
  push(P(`A consistency check with EPCAPE is possible. Dedrick et al. (2026) report parcel-based supersaturations of 0.03–0.09%, which they attribute to high aerosol concentrations (median above 2000 cm⁻³ for particles larger than 10 nm), low sub-cloud updraft speed (median below 0.2 m s⁻¹) and narrow updraft variability. Putting illustrative values C = 1000 cm⁻³, k = 0.7 and w = 20 cm s⁻¹ into Eqs. 7.8–7.9 gives s_{max} ≈ 0.14% and N_{d} ≈ 240 cm⁻³. Many nuclei and gentle updrafts place these clouds at the low-supersaturation, updraft-limited end of Figure 6, the same placement that Section 12.3 infers from the regime boundaries of Reutter et al. (2009). The values of C and k are chosen for illustration and are not fitted to EPCAPE data, and Dedrick et al. (2026) caution that at high particle concentrations kinetic limitations, which equilibrium activation schemes neglect, become important. The number is indicative only.`));
  push(PB("What this explains. ", `Twomey's (1959) result that N_{d} depends on both aerosol and updraft, and on aerosol only sub-linearly (Section 2). The physically plausible range of 0–1 for ACI_{N} and the value near 0.5 found at Point Reyes (Section 4.2). The regime diagram of Reutter et al. (2009) (Section 4.4). The emphasis on vertical-velocity variance as the other determinant of N_{d} in stratus (Section 5.4). The 12–35% damping of the Twomey effect by the competition response at LASIC (Dedrick et al., 2025; Section 6.5).`));

  // ------------------------------------------------------------------ 7.5
  push(H2("7.5 Growth by condensation: fast when small, slow when large"));
  push(PB("The question. ", `Once activated, how fast do droplets grow, and what does that do to their size distribution?`));
  push(P(`An activated droplet grows by diffusion of vapor to its surface. Two things limit the rate. Vapor has to diffuse through the air to reach the droplet, and the latent heat released on condensation warms the droplet and has to be conducted away. Rogers and Yau (1989, Eq. 7.17) combine both, for a droplet large enough that curvature and solute can be ignored, into`));
  push(Eq(["r ", fr("dr", "dt"), " = ", fr("S − 1", [sub("F", "k"), " + ", sub("F", "d")]), " ≡ ξ"]));
  push(P(`where F_{k} is the heat-conduction term and F_{d} the vapor-diffusion term; both depend only on temperature and pressure. They write ξ = (S − 1) ξ_{1}, where the normalized growth parameter ξ_{1} is 68.2 μm² s⁻¹ at 80 kPa and 0 °C. Integrating gives a parabolic law (Rogers and Yau, 1989, Eq. 7.19):`));
  push(Eq(["r", pr("t"), " = ", rt([ss("r", "0", "2"), " + 2ξt"])]));
  push(P(`The key feature is the factor r on the left of Eq. 7.10. Radius grows quickly when the droplet is small, because little water is needed to add a micrometer, and slowly when it is large. Figure 7a shows the consequence. At a supersaturation of 0.05%, a droplet growing on the smallest of three sodium chloride nuclei reaches 10 μm in 45 minutes, needs 2.4 hours to reach 20 μm, and needs more than 12 hours to reach 50 μm (2700, 8500 and 44,500 s; Rogers and Yau, 1989, Table 7.2). A larger nucleus gives a head start, but beyond about 10 μm the growth rates are about the same whatever the nuclear mass (Rogers and Yau, 1989).`));
  push(P(`The same feature narrows the size distribution. For two droplets growing in the same environment, Eq. 7.11 says that the difference of the squares of their radii stays constant, so (Rogers and Yau, 1989)`));
  push(Eq([sub("r", "2"), pr("t"), " − ", sub("r", "1"), pr("t"), " = ", fr([ss("r", "2", "2"), pr("0"), " − ", ss("r", "1", "2"), pr("0")], [sub("r", "2"), pr("t"), " + ", sub("r", "1"), pr("t")])]));
  push(P(`and the difference in radii shrinks as both grow (Figure 7b). Small droplets catch up. Condensation in a steady updraft therefore produces droplets of similar size, and Rogers and Yau (1989) note that spectra calculated this way are narrower than those observed.`));
  push(Fig("fig07_growth.png", `Growth by condensation. (a) Radius against time at 0.05% supersaturation, 90 kPa and 273 K, starting from 0.75 μm: the parabolic law (Eq. 7.11, with ξ_{1} = 63.7 μm² s⁻¹ computed here from Eq. 7.10 for these conditions) and the numerical results tabulated by Rogers and Yau (1989, Table 7.2, from Mason, 1971) for sodium chloride nuclei of three masses. (b) Two droplets starting at 2 and 8 μm in the same 0.2% supersaturation: their separation shrinks from 6 μm to 2.2 μm in ten minutes (Eq. 7.12).`,
    "Left: droplet radius against time on log axes, parabolic law with tabulated points. Right: two droplets of different initial radius converging in size over ten minutes."));
  push(P(`Two conclusions follow, and the rest of this section leans on both. First, the mean droplet size in a cloud is set mainly by bookkeeping, not by growth kinetics. The condensed water at a given height above cloud base is fixed by thermodynamics (Section 7.7), and it is shared among however many droplets were activated at cloud base, so more droplets means smaller droplets. This is the pattern Squires found: continental cumulus with many small droplets in a narrow spectrum, maritime cumulus with fewer and larger droplets in a broader one, at similar liquid water content (Rogers and Yau, 1989, Ch. 5). Second, condensation alone is too slow to make rain. Rain can appear within about 20 minutes of a cumulus forming, yet growing a droplet to 20 μm in 10 minutes by condensation would need a supersaturation of about 0.5%, which for typical droplet concentrations requires a sustained updraft of 5 m s⁻¹ or more (Rogers and Yau, 1989, Ch. 8). Stratocumulus updrafts are far weaker. Something else has to make the large drops.`));
  push(P(`Real spectra are broader than Eq. 7.12 predicts, and Rogers and Yau (1989, Ch. 8) point to mixing with dry air as the most likely reason. They distinguish two limits, following Baker and Latham (1979). In homogeneous mixing the entrained air mixes quickly, every droplet sees the same subsaturation, and all of them shrink. In inhomogeneous mixing evaporation is fast compared with mixing, so some droplets evaporate completely while the rest are diluted without changing size. Which limit applies matters for the radiative response, because one reduces droplet size and the other droplet number (an inference of this review); Yum et al. (2015) and Yeom et al. (2021), both in the project folder, examine which limit stratocumulus observations favor.`));
  push(PB("What this explains. ", `The relation Δr_{e}/r_{e} ≈ −(1/3)ΔN/N at fixed water (Section 3.3). Why droplets are smaller over continents than over oceans (Sections 3.4 and 4.1). Why observed droplet-spectrum width, which condensation alone cannot produce, is a live issue for the dispersion effect (Section 12.3, Candidate C).`));

  // ------------------------------------------------------------------ 7.6
  push(H2("7.6 Why droplet size controls rain"));
  push(PB("The question. ", `Why would a cloud with more, smaller droplets rain less?`));
  push(P(`Rain in a warm cloud forms by collision and coalescence. A droplet somewhat larger than its neighbors falls faster, overtakes them, and merges with some of those in its path (Rogers and Yau, 1989, Ch. 8; Ardon-Dryer and Garimella, 2014b). Two size dependences make the process extremely sensitive to droplet radius. The first is fall speed. A small droplet falls at the speed at which drag balances weight, which for radii below about 30 μm is the Stokes speed (Rogers and Yau, 1989, Ch. 8):`));
  push(Eq(["u", pr("r"), " = ", sub("k", "1"), " ", sup("r", "2")]));
  push(P(`with k_{1} ≈ 1.19 × 10⁶ cm⁻¹ s⁻¹. A 10-μm droplet falls at about 1 cm s⁻¹ and a 20-μm droplet at about 5 cm s⁻¹; a raindrop of 1 mm radius falls at about 650 cm s⁻¹ (Figure 8a; Rogers and Yau, 1989, Fig. 6.1 and Table 8.1). The second is collision efficiency. A falling drop pushes air aside, and small droplets tend to follow the air around it and miss. The fraction of droplets in the geometric path that actually collide is tiny when the collector is small. For a 10-μm collector it never exceeds about 5%; for a 20-μm collector it reaches 17%; for a 40-μm collector it reaches 75% (Rogers and Yau, 1989, Table 8.2; Figure 8b). A drop smaller than about 18 μm collides with only a minute fraction of the droplets in its path, so a cloud with negligible numbers of drops larger than that is relatively stable against coalescence (Rogers and Yau, 1989, Ch. 6). Collisions do not occur in significant numbers until some droplets reach about 20 μm, after which the collision rate rises in proportion to at least the fourth power of radius (Rogers and Yau, 1989, Ch. 8).`));
  push(P(`Once a collector drop of radius R is much larger than the droplets it sweeps up, its growth rate is approximately (Rogers and Yau, 1989, Eq. 8.15)`));
  push(Eq([fr("dR", "dt"), " = ", fr(["Ē L u", pr("R")], ["4", sub("ρ", "L")])]));
  push(P(`where Ē is an average collection efficiency and L the liquid water content (Rogers and Yau write M). With u and Ē both rising with R, growth accelerates once it starts. Of the order of 10⁵ collisions make one raindrop of 1 mm diameter (Rogers and Yau, 1989; Ardon-Dryer and Garimella, 2014b).`));
  push(Fig("fig08_fall.png", `Why coalescence needs large droplets. (a) Terminal fall speed against drop radius: the Stokes law (Eq. 7.13), the linear law u = k_{3}r with k_{3} = 8 × 10³ s⁻¹ for intermediate sizes, and the measurements of Gunn and Kinzer (1949) as tabulated by Rogers and Yau (1989, Table 8.1). (b) Collision efficiency for collector drops of radius R = 10 to 40 μm capturing droplets of radius r, from Rogers and Yau (1989, Table 8.2). Rows of that table for larger collectors are omitted because their column alignment could not be recovered with certainty from the digitized text.`,
    "Left: terminal fall speed against drop radius on log axes with measured points. Right: collision efficiency against collected droplet radius for four collector sizes."));
  push(P(`Now add the bookkeeping of Section 7.5. At fixed liquid water the mean droplet radius scales as N_{d}^{−1/3}. A cloud holding 0.5 g m⁻³ of water has a mean-volume radius of 13.4 μm if N_{d} = 50 cm⁻³ and 8.4 μm if N_{d} = 200 cm⁻³ (computed here from Eq. 7.16). In the first cloud a droplet needs to be only a third larger than the mean to reach the 18-μm threshold. In the second it needs to be more than twice the mean, which a spectrum narrowed by condensation (Section 7.5) is unlikely to supply. That is the physical content of Albrecht's (1989) hypothesis (Section 3.2): more aerosol, smaller droplets, less efficient coalescence, less drizzle, and so more water kept in the cloud. Wood's notes on that paper stress how sensitive drizzle is to droplet size, and they add what later work showed: suppression of precipitation by aerosol is clear in warm stratiform clouds, but models that resolve cloud dynamics do not always produce more cloud as a result (Wood, 2015, notes on Albrecht, 1989).`));
  push(P(`The sensitivity of rain rate R to droplet number is summarized by the precipitation susceptibility, −dln R/dln N_{d}. Wood's notes on Stevens and Feingold (2009) compile values of 1–1.5 from stratocumulus field observations, 1.0–3.3 in the autoconversion parameterizations used in models, and 0.1–1.1 from CloudSat and AMSR satellite data (Wood, 2015). The spread across methods and regimes fits the buffered-system argument of that paper (Section 4.4).`));
  push(PB("What this explains. ", `The Albrecht hypothesis (Section 3.2). The liquid-water increase in the FIRE ship tracks, interpreted as drizzle suppression (Section 3.1). The open-cell ship tracks of Christensen and Stephens (2011), in which polluted clouds held 39% more liquid water (Section 5.1). The positive branch at low N_{d} of the inverted-V relationship between LWP and N_{d}, as it is usually interpreted (Section 6.3). The absence of a positive branch at EPCAPE, where precipitating cases were rare (Zhang et al., 2025; Section 6.5).`));

  // ------------------------------------------------------------------ 7.7
  push(H2("7.7 From droplets to light: optical depth"));
  push(PB("The question. ", `How does a population of droplets attenuate sunlight, and why does droplet number matter when the amount of water is fixed?`));
  push(P(`A droplet removes light from a beam mainly by scattering it. The amount removed is expressed as an extinction cross-section, written as the geometric cross-section πr² times an extinction efficiency Q_{ext}. For particles much larger than the wavelength, Q_{ext} approaches 2. A large particle removes twice the light that its shadow suggests, because in addition to the light it intercepts, an equal amount is diffracted at its edge; Bohren and Clothiaux (2006, Sec. 3.5, Eq. 3.139) discuss this as the extinction paradox. Cloud droplets are tens of wavelengths across in visible light, and the Mie calculation in Figure 9 shows Q_{ext} oscillating and settling toward 2 across the droplet size range (its average between 5 and 15 μm radius is 2.09). Wood's notes on Twomey (1977) take Q_{ext} = 2 as the starting point (Wood, 2015).`));
  push(Fig("fig10_mie.png", `Extinction efficiency of a non-absorbing water sphere (refractive index 1.333) at a wavelength of 0.55 μm, computed for this review with Mie theory (the miepython package). Across the cloud-droplet size range (shaded) the efficiency is close to the large-particle limit of 2 (dashed), the approximation used by Wood (2015) and discussed by Bohren and Clothiaux (2006, Sec. 3.5). At aerosol sizes, extinction per particle rises steeply with size.`,
    "Extinction efficiency against droplet radius on a log axis, oscillating and converging toward 2 for cloud droplet sizes."));
  push(P(`With Q_{ext} = 2, the optical depth of a layer of thickness h holding N_{d} droplets of radius r per unit volume is twice the total cross-sectional area of droplets above a unit area of ground (Wood, 2015, notes on Twomey, 1977):`));
  push(Eq(["τ = 2π ", sub("N", "d"), " ", sup("r", "2"), " h"]));
  push(P(`The liquid water content is the total droplet volume times the density of water ρ_{w}:`));
  push(Eq(["L = ", fr("4", "3"), " π ", sub("ρ", "w"), " ", sub("N", "d"), " ", sup("r", "3")]));
  push(P(`Eliminating N_{d} between the two gives τ in terms of water and droplet size. Eliminating r gives it in terms of water and droplet number (Wood, 2015):`));
  push(Eq(["τ = ", fr("3 L h", ["2 ", sub("ρ", "w"), " r"]), " = ", fr("3 LWP", ["2 ", sub("ρ", "w"), " r"])]));
  push(Eq(["τ = 2π h ", sup(pr(fr("3L", ["4π", sub("ρ", "w")])), "2/3"), " ", ss("N", "d", "1/3"), "  ∝  ", ss("N", "d", "1/3"), " ", sup("L", "2/3"), " h"]));
  push(P(`Figure 10 is the Twomey effect in one picture. Take a fixed volume of water and divide it into eight droplets. Then divide the same water into sixty-four droplets of half the radius. Volume goes as r³, so halving the radius takes eight times as many droplets. Cross-sectional area goes as r², so each new droplet has a quarter of the area. Eight times a quarter is two: the same water now casts twice the shadow. In general the area presented by a fixed mass of water goes as 1/r (Eq. 7.17), or equivalently as N_{d}^{1/3} (Eq. 7.18). The cube root is a weak dependence, and two numbers are worth remembering: doubling N_{d} raises τ by 26%, and it takes an eightfold increase to double it. Li et al. (2017) put the same thing in words: at fixed water, more and smaller droplets present a larger total cross-section and scatter more sunlight.`));
  push(Fig("fig09_dots.png", `The same water in more droplets. (a) Eight droplets of radius r. (b) Sixty-four droplets of radius r/2, which hold the same volume of water and present twice the total cross-sectional area; panels (a) and (b) are drawn to the same scale. (c) The resulting dependence of optical depth on droplet number at fixed liquid water and cloud thickness (Eq. 7.18). Schematic drawn for this review.`,
    "Two boxes of circles, eight large and sixty-four small, and a curve of relative optical depth rising as the cube root of relative droplet number."));
  push(P(`A worked example fixes the magnitudes. A cloud 300 m thick with L = 0.3 g m⁻³ (LWP = 90 g m⁻²) and N_{d} = 100 cm⁻³ has r ≈ 9.0 μm and τ ≈ 15.1. Doubling N_{d} to 200 cm⁻³ with the same water gives r ≈ 7.1 μm and τ ≈ 19.0 (computed here from Eqs. 7.15–7.16).`));
  push(P(`Real clouds hold a distribution of sizes n(r), and the right average follows from the same two relations. Optical depth depends on the second moment of the size distribution and liquid water on the third, so the radius that belongs in Eq. 7.17 is the ratio of the two, the effective radius:`));
  push(Eq([sub("r", "e"), " = ", fr([integ(["n", pr("r"), " ", sup("r", "3"), " dr"])], [integ(["n", pr("r"), " ", sup("r", "2"), " dr"])])]));
  push(P(`Bohren and Clothiaux (2006, Sec. 5.3.1) arrive at the same ratio, written in terms of diameter as the mean cube over the mean square, as the size that characterizes a cloud's absorption relative to its scattering. Their Fig. 3.10 shows why it is larger than the typical droplet: in a stratus size distribution the number of droplets peaks near 6 μm diameter, the contribution to visible scattering near 16 μm, and the volume near 20 μm. Because r_{e} always exceeds the mean-volume radius, by an amount that grows with the width of the distribution, a broader spectrum at the same L and N_{d} has a larger r_{e} and a smaller τ. This is the dispersion effect. If added aerosol broadens the droplet spectrum, part of the Twomey brightening is cancelled (Liu and Daum, 2002); Wood's notes on Jones et al. (1994) discuss the spectral-width parameter of Martin et al. (1994) through which this enters models (Wood, 2015).`));
  push(P(`One refinement matters for every retrieval used at EPCAPE. In a real stratocumulus the liquid water content is not uniform. In air rising without mixing it follows the adiabatic liquid water content (Rogers and Yau, 1989, Ch. 2), which over the few hundred meters of a stratocumulus layer increases nearly linearly with height above cloud base, while N_{d} stays roughly constant because droplets activate only near cloud base (Section 7.4). Droplet radius then grows as the cube root of height and extinction as height to the two-thirds power (Figure 11). Integrating Eq. 7.15 through such a cloud changes the exponents of Eq. 7.18 to`));
  push(Eq(["τ  ∝  ", ss("N", "d", "1/3"), " ", sup("LWP", "5/6")]));
  push(P(`which is the form behind the susceptibility expressions of Section 6.3. The same integration gives LWP = (5/9) ρ_{w} τ r_{e}, with r_{e} taken at cloud top, in place of the factor 2/3 for a vertically uniform cloud in Eq. 7.17, and combining the two gives N_{d} proportional to τ^{1/2} r_{e}^{−5/2}. These three relations were re-derived here from Eqs. 7.15–7.16 with a linear L(z) and constant N_{d}; they are the standard adiabatic relations, but the derivation is this review's and should be checked against the retrieval literature before use (Grosvenor et al., 2018). They carry three practical messages. Optical depth is 2.5 times more sensitive to LWP than to N_{d}, in the exponents. The droplets that matter most for sunlight are the large ones near cloud top. And a retrieval of N_{d} from τ and r_{e} is far more sensitive to error in r_{e} than to error in τ, which is consistent with the finding of Grosvenor et al. (2018) that r_{e} errors dominate the uncertainty (Section 5.2).`));
  push(Fig("fig11_adiabatic.png", `An idealized adiabatic cloud 300 m thick in which liquid water content rises linearly from zero at cloud base to 0.6 g m⁻³ at cloud top (LWP = 90 g m⁻², as in the worked example). (a) The liquid water profile, the same in both cases. (b) Droplet radius for N_{d} = 50 and 200 cm⁻³; the cloud-top radii are 14.2 and 8.9 μm. (c) Extinction; the integrated optical depths are 11.4 and 18.1, a ratio of 4^{1/3}. Computed for this review from Eqs. 7.15–7.16.`,
    "Three profiles against height above cloud base: liquid water rising linearly, droplet radius for two droplet numbers, and extinction for two droplet numbers."));
  push(PB("What this explains. ", `Twomey's albedo hypothesis and the N_{d}^{1/3} scaling quoted in Section 2. Smaller droplets and higher visible reflectance appearing together in ship tracks (Section 3.1). Why Feingold et al. (2003) insisted on comparing clouds of similar LWP: at different LWP a difference in r_{e} says nothing about N_{d} (Section 4.2). Why LWP explained most of the variance in the fourteen-year record of Sena et al. (2016) (Section 5.2). Why N_{d} retrievals are so sensitive to r_{e} (Section 5.2).`));

  // ------------------------------------------------------------------ 7.8
  push(H2("7.8 From optical depth to albedo and transmission"));
  push(PB("The question. ", `How much sunlight does a cloud of optical depth τ reflect, and why does the answer saturate?`));
  push(P(`A photon entering a cloud is scattered many times and, at visible wavelengths, almost never absorbed. Each scattering by a cloud droplet sends it mostly forward. The asymmetry parameter g, the mean cosine of the scattering angle, is about 0.85 for cloud droplets (Bohren and Clothiaux, 2006, Ch. 5). A photon therefore has to be scattered several times before its direction is randomized, and what counts for reflection is not τ but the scaled optical thickness τ(1 − g). Bohren and Clothiaux (2006, Sec. 5.2, Eqs. 5.51–5.52) derive the reflectivity R and transmissivity T of a non-absorbing layer from a two-stream model, in which light travels only up or down:`));
  push(Eq2(["R = ", fr("τ(1 − g)/2", "1 + τ(1 − g)/2")], ["T = ", fr("1", "1 + τ(1 − g)/2")]));
  push(P(`They motivate the result with a pile of glass plates. Each plate reflects a little, and a thick enough pile reflects nearly everything although no plate absorbs anything. A cloud is white for the same reason. With g = 0.85, Eq. 7.21 becomes R = τ/(τ + 13.3). Wood's notes on Twomey (1977) use the approximation (Wood, 2015)`));
  push(Eq(["α ≈ ", fr("τ", "τ + 7")]));
  push(P(`The two expressions have the same form, α = τ/(τ + c), and differ in the constant. The constant depends on how the two-stream model treats the angular distribution of the light and on the sun angle, so neither value should be used for quantitative work; a radiative transfer code such as libRadtran (Emde et al., 2016) is the tool for that. This remark is this review's, not a statement from either source. The intuition does not depend on c. The curve saturates (Figure 12a): thin clouds brighten quickly as τ increases, and thick clouds are already bright. In the worked example of Section 7.7, doubling N_{d} raised τ from 15.1 to 19.0. That raises the albedo from 0.68 to 0.73 with c = 7, or from 0.53 to 0.59 with c = 13.3: five to six percentage points either way.`));
  push(P(`The susceptibility follows in two lines. For any albedo of the form α = τ/(τ + c),`));
  push(Eq([fr("dα", "dτ"), " = ", fr("c", sup(pr("τ + c"), "2")), " = ", fr(["α", pr("1 − α")], "τ")]));
  push(P(`and at fixed liquid water Eq. 7.18 gives dln τ/dln N_{d} = 1/3, so`));
  push(Eq2([fr("dα", ["d ", fn("ln", sub("N", "d"))]), " = ", fr(["α", pr("1 − α")], "3")], [fr("dα", ["d", sub("N", "d")]), " = ", fr(["α", pr("1 − α")], ["3 ", sub("N", "d")])]));
  push(P(`The constant c has dropped out, so the result is the same for both curves in Figure 12a (this observation is this review's). The formula itself is the one Wood (2015) attributes to Platnick and Twomey (1994), noting that it does not appear in Twomey's original papers. Equation 7.24 can be read two ways (Figure 12b). In logarithmic form the susceptibility depends only on albedo and is largest, 1/12, at α = 0.5, in a cloud that is neither thin nor saturated. A 10% increase in N_{d} at that albedo raises it by about 0.008. In absolute form the susceptibility also carries a factor 1/N_{d}: one more droplet per cubic centimeter matters far more in a cloud with 20 cm⁻³ than in one with 500 cm⁻³. Clean clouds are the susceptible ones (Wood, 2015, notes on Twomey, 1977).`));
  push(Fig("fig12_albedo.png", `From optical depth to albedo. (a) Cloud albedo against optical depth from the approximation in Wood's notes (Eq. 7.22) and from the two-stream result of Bohren and Clothiaux (2006, Eq. 5.51) with g = 0.85 (Eq. 7.21). Dots mark the worked example of Section 7.7 (τ = 15.1 and 19.0). (b) Albedo susceptibility at fixed liquid water (Eq. 7.24), which is the same for both curves in (a).`,
    "Left: albedo rising and saturating with optical depth for two approximations. Right: susceptibility as an inverted parabola in albedo peaking at one half."));
  push(P(`The surface sees the complement. For a non-absorbing cloud T = 1 − R, so every statement about albedo is also a statement about transmission with the sign reversed. That is the starting point of the surface-radiation argument in Section 8. Two features of transmission deserve intuition of their own. First, a cloud transmits more than exponential attenuation would suggest (Figure 13a). Attenuation would be exponential only if light scattered out of the downward direction never returned to it; multiple scattering gives it further chances (Bohren and Clothiaux, 2006, Sec. 5.2, Fig. 5.11). Scattered light is not lost. It is redirected, and much of it eventually leaves through the bottom. The contrast with the unscattered direct beam is starker still: by Eq. 7.21 a cloud with a scaled optical thickness of 2 (τ ≈ 13) transmits half the incident sunlight, although its direct beam is attenuated by a factor of e⁻¹³, to about two parts in a million. Second, the diffuse light reaching the surface is not monotonic in τ. It is the total transmitted light minus what is left of the direct beam (Bohren and Clothiaux, 2006, Eq. 5.66):`));
  push(Eq([fr([sub("D", "↓")], [sub("F", "0")]), " = ", fr("1", "1 + τ(1 − g)/2"), " − ", sup("e", "−τ")]));
  push(P(`This rises from zero under a clear sky, peaks for a thin cloud near τ = (1/g) ln[2/(1 − g)], which is about 3 for g = 0.85, and then declines (Figure 13b; the approximation for the maximum holds for g above 0.5). In the words of Bohren and Clothiaux (2006), clouds are both givers and takers of light: a thin cloud makes the sky away from the sun brighter than a clear sky, and a thick one makes it darker. Any surface instrument that separates direct from diffuse light, such as the MFRSR, sees both regimes.`));
  push(Fig("fig13_transmit.png", `Transmission by a non-absorbing cloud, after Bohren and Clothiaux (2006, Figs. 5.11 and 5.13), recomputed from their equations. (a) Transmissivity against scaled optical thickness τ(1 − g) with multiple scattering (Eq. 7.21) compared with the exponential exp[−τ(1 − g)/2] that would hold if scattered light never returned to the downward direction. (b) Diffuse downward irradiance beneath the cloud as a fraction of the incident irradiance (Eq. 7.25) for four values of the asymmetry parameter; dots mark the maxima. g = 0 corresponds to molecular scattering and the higher values to cloud droplets.`,
    "Left: transmissivity against scaled optical thickness, multiple scattering compared with exponential decay. Right: diffuse irradiance below cloud against optical thickness for four asymmetry parameters, each rising to a maximum and declining."));
  push(PB("What this explains. ", `Twomey's (1977) finding that brightening dominates for thin to moderately thick clouds (Section 2). The susceptibility framework of Twomey (1991) and Platnick and Twomey (1994), and the higher susceptibility of clean marine stratus (Section 3.3). The (1 − A_{c})/3 factor in the susceptibility expressions of Feingold et al. (2022) and Goren et al. (2026), which is Eq. 7.24 divided by albedo (Section 6.3). The transmission-susceptibility expression of Section 8.`));

  // ------------------------------------------------------------------ 7.9
  push(H2("7.9 Absorption and the near-infrared: how droplet size is seen from outside"));
  push(PB("The question. ", `If visible reflectance depends on optical depth, how can a radiometer tell droplet size? And why did Twomey worry about absorption?`));
  push(P(`Liquid water is nearly transparent in the visible and absorbs weakly in the near-infrared. For a droplet that is large compared with the wavelength and weakly absorbing, the scattering cross-section is about twice its geometric area, C_{sca} ≈ 2πa² for radius a, while the absorption cross-section is proportional to its volume, C_{abs} ≈ κ_{w}v, where κ_{w} is the absorption coefficient of bulk water and v the droplet volume (Bohren and Clothiaux, 2006, Sec. 5.3.1). Dividing C_{abs} by C_{sca} gives the chance that a photon is absorbed in a single encounter, which is one minus the single-scattering albedo ω_{0}:`));
  push(Eq(["1 − ", sub("ω", "0"), " ≈ ", fr([sub("κ", "w"), " v"], ["2π", sup("a", "2")]), " = ", fr([sub("κ", "w"), " ", fr("4", "3"), "π", sup("a", "3")], ["2π", sup("a", "2")]), " = ", fr([sub("κ", "w"), " d"], "3")]));
  push(P(`with d the droplet diameter (the ratio is this review's algebra from the two approximations just quoted). Absorption goes with volume and scattering with area, so the absorbed fraction per scattering is proportional to droplet size. For a size distribution, d is the mean cube of the diameter divided by its mean square (Bohren and Clothiaux, 2006), which is twice the effective radius of Eq. 7.19.`));
  push(P(`The fraction is tiny, but multiple scattering amplifies it. For a cloud so thick that nothing is transmitted, the two-stream reflectivity is (Bohren and Clothiaux, 2006, Eq. 5.72)`));
  push(Eq([sub("R", "∞"), " = ", fr([rt(["1 − ", sub("ω", "0"), "g"]), " − ", rt(["1 − ", sub("ω", "0")])], [rt(["1 − ", sub("ω", "0"), "g"]), " + ", rt(["1 − ", sub("ω", "0")])])]));
  push(P(`Figure 14 plots it. In visible light, with κ_{w} of order 0.1 m⁻¹ and d of order 10 μm (the values used by Bohren and Clothiaux, 2006), the absorbed fraction is about 3 × 10⁻⁷ and the reflectivity is 0.997. But the curve bends early. Absorbing one photon in a thousand at each scattering limits the reflectivity of a thick cloud to 0.85, because each photon is scattered a great many times before it escapes. Bohren and Clothiaux (2006) make the same point from the other direction: a cloud's droplets occupy about one millionth of its volume, yet for attenuation the cloud is equivalent to a slab of water nearly a thousand times thicker than its liquid water path. In their words, a little bit of absorption goes a long way.`));
  push(Fig("fig16_absorb.png", `Reflectivity of a very thick cloud against the fraction of light absorbed at each scattering event, from the two-stream result of Bohren and Clothiaux (2006, Eq. 5.72) with g = 0.85 (Eq. 7.27). Blue dots: visible light with the values of κ_{w} and d used by Bohren and Clothiaux, and an absorbed fraction of 0.001. Orange dots: the effect of doubling droplet size at an absorbing wavelength, starting from an illustrative absorbed fraction of 0.0033. Computed for this review.`,
    "Reflectivity of a thick cloud falling from near one as the absorbed fraction per scattering increases from ten to the minus seven to ten to the minus one."));
  push(P(`This is how droplet size is measured from outside a cloud. At a visible wavelength, reflectance depends on τ and hardly at all on droplet size. At an absorbing near-infrared wavelength, Eq. 7.26 makes the absorbed fraction proportional to droplet size, and Figure 14 shows the reflectance responding: doubling the droplet size at an absorbed fraction of 0.0033 lowers the thick-cloud reflectivity from 0.74 to 0.66. Two wavelengths constrain two unknowns, τ and r_{e}. It is also why ship tracks stand out at 3.7 μm, where their smaller droplets absorb less and reflect more than the surrounding cloud (Coakley et al., 1987; Section 3.1). In transmission the size signal is weaker, which is the problem McBride et al. (2011) addressed (Section 8).`));
  push(P(`The same curve explains the second half of Twomey's (1977) paper (Section 2). If pollution adds absorbing material to a cloud, the absorbed fraction rises, and Figure 14 shows how little it takes to matter in a thick cloud. A thin cloud gains more from the added droplets than it loses to the added absorption, and brightens. A thick cloud is already near the top of the curve in Figure 12a, gains little from more droplets, and can darken.`));
  push(PB("What this explains. ", `The 3.7-μm signature of ship tracks (Section 3.1). The two competing effects in Twomey (1977) (Section 2). The physical basis of the r_{e} retrievals whose disagreements Section 5.2 describes, and of the proposal's argument that a near-infrared pyranometer is more sensitive to r_{e} than a broadband one (Section 12.3, Candidate D).`));

  // ------------------------------------------------------------------ 7.10
  push(H2("7.10 Why the cloud fights back: sedimentation, evaporation and entrainment"));
  push(PB("The question. ", `The Twomey argument holds liquid water fixed. Why would the amount of liquid water change when the droplets get smaller?`));
  push(P(`A stratocumulus deck is maintained by turbulence, and the turbulence mixes warm, dry air from above the inversion down into the cloud. This is entrainment. Entrained air evaporates cloud water, so entrainment thins the cloud, and how much air is entrained depends on what the droplets near cloud top are doing (Wood, 2015, notes on Ackerman et al., 2004, and on Bretherton et al., 2007). Two properties of small droplets matter there.`));
  push(P(`The first is sedimentation. Droplets fall relative to the air at the Stokes speed of Eq. 7.13, which goes as r². At fixed liquid water r goes as N_{d}^{−1/3}, so the fall speed of the mean droplet goes as N_{d}^{−2/3}: a fourfold increase in N_{d} cuts it by a factor of 2.5 (Figure 15b; this scaling is derived here from Eqs. 7.13 and 7.16). In a clean cloud, sedimentation steadily carries liquid water downward, away from the interface where entrainment happens. In a polluted cloud the droplets stay where they are.`));
  push(P(`The second is evaporation. The law that governs growth also governs evaporation (Eq. 7.10 with S below 1), so the time for a droplet to evaporate completely goes as r², and the distance it falls in that time goes as r⁴. In air at 80% relative humidity a 10-μm droplet survives a fall of about 2 cm, a 30-μm droplet 1.7 m, and a 100-μm drizzle drop about 200 m (Rogers and Yau, 1989, Table 7.3; Figure 15a). Cloud droplets mixed into dry air vanish almost at once, and the smaller they are the faster they go. Li et al. (2017) describe the consequence: smaller droplets evaporate more readily, and the resulting evaporative cooling reduces the buoyancy of the cloudy air.`));
  push(Fig("fig14_evap.png", `Two size-dependent processes at cloud top. (a) Distance a drop falls before evaporating completely in air at 280 K and 80% relative humidity, from Rogers and Yau (1989, Table 7.3), with a fourth-power law drawn through the 10-μm value for comparison. (b) Stokes fall speed (Eq. 7.13) of the mean-volume droplet against droplet number at two liquid water contents, computed for this review from Eq. 7.16.`,
    "Left: distance fallen before evaporating against initial drop radius on log axes, following a fourth-power law. Right: fall speed of the mean droplet decreasing as droplet number increases."));
  push(P(`Put the two together at cloud top. With more and smaller droplets, more liquid water sits in the thin layer where cloud and dry air meet, and it evaporates more readily when dry air is mixed in. Evaporation cools the mixture and makes it denser, so it sinks into the cloud more easily, and entrainment becomes more efficient. More warm, dry air is drawn in, and the cloud loses water. Bretherton et al. (2007) isolated this entrainment–sedimentation feedback. In their simulations sedimentation reduced entrainment and raised LWP, not by weakening the turbulence but by removing liquid from the entrainment zone and so reducing the evaporative cooling there; the controlling parameter is the ratio of the sedimentation speed to the convective velocity scale, w_{sed}/w∗ (Wood, 2015, notes on Bretherton et al., 2007; Section 4.3). Ackerman et al. (2004) had found a related chain: more droplets suppress precipitation, turbulence strengthens, entrainment increases, and LWP falls when the air above the inversion is dry (Wood, 2015, notes on Ackerman et al., 2004; Section 4.3).`));
  push(P(`The liquid water of the cloud therefore responds to aerosol through two channels of opposite sign (Figure 1). Where the cloud drizzles, smaller droplets suppress the rain and water accumulates, so LWP rises (Section 7.6). Where it does not, smaller droplets enhance entrainment drying, so LWP falls. Which channel wins depends on whether the cloud is precipitating, on the humidity above the inversion, on cloud-base height, and on the time allowed (Ackerman et al., 2004; Wood, 2007; Sections 4.3 and 5.5).`));
  push(P(`The radiative consequence can be written in one line. With the adiabatic scaling of Eq. 7.20, letting LWP vary gives dln τ/dln N_{d} = 1/3 + (5/6) dln LWP/dln N_{d}, and Eq. 7.23 turns this into`));
  push(Eq([fr("dα", ["d ", fn("ln", sub("N", "d"))]), " = ", fr(["α", pr("1 − α")], "3"), " ", br(["1 + ", fr("5", "2"), " ", fr(["d ", fn("ln", "LWP")], ["d ", fn("ln", sub("N", "d"))])])]));
  push(P(`which, divided by α, is the susceptibility in the form used by Feingold et al. (2022) and Goren et al. (2026) (Section 6.3). The first factor is the Twomey effect. The bracket is the adjustment (Figure 16). Because τ is 2.5 times more sensitive to LWP than to N_{d}, a modest LWP slope has a large effect. A slope of −0.4 cancels the Twomey effect exactly, and anything more negative means net darkening. For scale, a slope of −0.4 means that doubling N_{d} reduces LWP by 24%.`));
  push(Fig("fig15_net.png", `Net albedo susceptibility as a multiple of the Twomey susceptibility, 1 + (5/2) dln LWP/dln N_{d} (the bracket of Eq. 7.28), against the LWP adjustment slope. Dots mark no LWP response, the slope of −0.4 at which the adjustment cancels the Twomey effect, and the slope of −1.1 reported for EPCAPE by Zhang et al. (2025).`,
    "Straight line of net susceptibility relative to the Twomey value against LWP adjustment slope, crossing zero at a slope of minus 0.4."));
  push(P(`Reported slopes fall on both sides of that threshold. Toll et al. (2019) find a weak average decrease in LWP that offsets about 23% of the Twomey cooling, which in Eq. 7.28 corresponds to a slope near −0.09 (this conversion is this review's). Goren et al. (2026) find slopes near −1 where intermediate-τ clouds dominate and a net susceptibility close to zero when morphologies are weighted by occurrence. Zhang et al. (2025) report −1.1 at EPCAPE, for which the bracket of Eq. 7.28 is −1.75. Whether slopes that steep are causal, or reflect co-variability between aerosol and meteorology, is the open question of Sections 6.3 and 10.1.`));
  push(P(`Two further ideas complete the picture. Stevens and Feingold (2009) generalized these compensations into the statement that clouds are a buffered system: a change imposed on one process tends to be opposed by the response of another, so the net response to aerosol is smaller than any single mechanism suggests (Wood, 2015, notes on Stevens and Feingold, 2009; Li et al., 2017). And adjustments take time. Droplet number responds in the minutes it takes air to rise through cloud base (Section 7.4), whereas the entrainment adjustment works through the heat and moisture budgets of the whole boundary layer. Wood (2007) found that the sign of the thickness response changes with time, and Glassmeier et al. (2021) showed that ship tracks are observed before the cloud has finished thinning (Sections 4.3 and 6.2). A measurement at one place and time, as at EPCAPE, samples clouds at unknown stages of adjustment.`));
  push(PB("What this explains. ", `The simulations of Ackerman et al. (2004) and Bretherton et al. (2007) and the mixed-layer analysis of Wood (2007) (Section 4.3). Closed-cell ship tracks losing liquid water while open-cell tracks gain it (Section 5.1). Negative N_{d}–LWP relationships in satellite data and their partial cancellation of the Twomey effect (Sections 5.5 and 6.3). The afternoon offset of brightening in the southeast Atlantic shipping corridor (Section 6.2). The entrainment-drying interpretation of the EPCAPE slope (Section 6.5).`));

  // ------------------------------------------------------------------ 7.11
  push(H2("7.11 The physics in one table"));
  push(P(`Box 1 collects the scalings of this section. Each row is one link of Figure 1, with the source to consult and the sections of this review that it explains.`));
  push(new Paragraph({ children: [new TextRun({ text: "Box 1. ", bold: true, font: FONT, size: 20 }), new TextRun({ text: "The scalings of Section 7 at a glance.", font: FONT, size: 20 })], spacing: { before: 120, after: 80 }, keepNext: true }));
  const bw = [1500, 2350, 2700, 1750, 1060];
  const rows = [
    ["Link", "Scaling", "In words", "Source", "Explains"],
    ["Activation barrier", "s^{∗} ∝ κ^{−1/2} D_{d}^{−3/2}", "Larger and more soluble particles activate first; size counts for more than composition", "Rogers and Yau (1989), Eqs. 6.7–6.8; Petters and Kreidenweis (2007)", "2, 3.2, 6.5"],
    ["CCN spectrum", "N_{CCN} = C s^{k}", "The aerosol as a cloud sees it", "Rogers and Yau (1989), Eq. 6.20", "4.1, 5.3"],
    ["Droplet number", "N_{d} ∝ C^{2/(k+2)} w^{3k/(2k+4)}", "Sub-linear in aerosol, because added nuclei lower the peak supersaturation; rises with updraft", "Twomey (1959); Rogers and Yau (1989), Eqs. 6.21–6.22", "2, 4.2, 4.4, 6.5"],
    ["Condensational growth", "r dr/dt = ξ, so r² grows linearly with time", "Fast when small, slow when large; the spectrum narrows; no rain from condensation alone", "Rogers and Yau (1989), Eqs. 7.17–7.19", "3.3, 3.4"],
    ["Droplet size at fixed water", "r ∝ (L/N_{d})^{1/3}", "Same water, more droplets, smaller droplets", "Wood (2015), notes on Twomey (1977)", "3.1, 3.3"],
    ["Rain formation", "u ∝ r²; few collisions below 18–20 μm", "Smaller droplets suppress drizzle, and LWP can rise", "Rogers and Yau (1989), Ch. 8", "3.2, 5.1"],
    ["Optical depth", "τ = 3 LWP/(2ρ_{w}r_{e}) ∝ N_{d}^{1/3} LWP^{5/6}", "Area per unit mass of water goes as 1/r", "Wood (2015); Bohren and Clothiaux (2006), Sec. 3.5", "2, 3.3, 4.2"],
    ["Albedo", "α ≈ τ/(τ + c)", "Reflection saturates: the pile of plates", "Bohren and Clothiaux (2006), Eq. 5.51; Wood (2015)", "2, 3.3"],
    ["Susceptibility", "dα/dln N_{d} = α(1 − α)/3", "Largest at α = 0.5 and, per added droplet, in clean clouds", "Platnick and Twomey (1994); Wood (2015)", "3.3, 6.3"],
    ["Near-infrared absorption", "1 − ω_{0} ≈ κ_{w}d/3", "Absorption per scattering grows with droplet size: the basis of r_{e} retrievals", "Bohren and Clothiaux (2006), Sec. 5.3.1", "3.1, 5.2, 8"],
    ["Evaporation and sedimentation", "Evaporation distance ∝ r⁴; fall speed ∝ N_{d}^{−2/3} at fixed L", "Smaller droplets stay at cloud top and evaporate fast: more entrainment, and LWP can fall", "Rogers and Yau (1989), Table 7.3; Wood (2015), notes on Bretherton et al. (2007)", "4.3, 5.5, 6.5"],
    ["Net response", "dα/dln N_{d} = [α(1 − α)/3][1 + (5/2) dln LWP/dln N_{d}]", "An LWP slope of −0.4 cancels the Twomey effect", "Feingold et al. (2022)", "6.3, 8, 12"]
  ];
  push(new Table({
    width: { size: tw, type: WidthType.DXA }, columnWidths: bw,
    rows: rows.map((r, i) => new TableRow({ cantSplit: true, tableHeader: i === 0, children: r.map((t, j) => cell(t, bw[j], i === 0, i === 0 ? "D9E2F3" : null)) }))
  }));
  push(new Paragraph({ children: [new TextRun({ text: "The last column lists the sections of this review that each row helps to explain.", font: FONT, size: 20, italics: true })], spacing: { before: 80, after: 200 } }));
  push(P(`Three cautions apply. The scalings describe idealized clouds: a single updraft, droplets of one size or an adiabatic profile, and plane-parallel radiative transfer. Each gives the leading behavior and is no substitute for a parcel model, a large-eddy simulation or a radiative transfer code. The items computed or derived here, and not taken from a source, are the simplified parcel integration of Figure 5, the illustrative size distribution of Figure 4a, the schematic of Figure 10, the adiabatic-cloud relations following Eq. 7.20, the independence of Eq. 7.24 from the two-stream constant, the sedimentation scaling of Section 7.10, the algebra of Eq. 7.26, and the EPCAPE consistency check of Section 7.4; each rests on the cited source equations but should be checked before it is relied on. Finally, Wood's notes are informal course material, and where they summarize a paper the paper itself is the primary source.`));

  return out;
};
